from typing import List, Tuple

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x]!= x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x!= root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            elif self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1

def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    uf = UnionFind(N)

    for u, v in edges:
        uf.union(u-1, v-1)

    roots = set()
    for i in range(N):
        roots.add(uf.find(i))

    # If all components are connected (i.e., there's only one root), return N.
    # Otherwise, return the number of components that are not connected.
    if len(roots) == 1:
        return N
    else:
        return N - len(roots) + 1

# Test the function
print(f(6, 5, [(1, 2), (1, 3), (1, 4), (2, 5), (2, 6)]))  # Output: 6
```

